public class ExceptionMaskingDemo {
    public static void main(String[] args) {
        try {
            doWork();
        } catch (Exception e) {
            System.out.println("Caught: " + e.getMessage());
            for (Throwable t : e.getSuppressed()) {
                System.out.println("Suppressed: " + t.getMessage());
            }
        }
    }

    private static void doWork() throws Exception {
        try (AutoCloseableResource resource = new AutoCloseableResource()) {
            throw new Exception("Primary exception from try block");
        }
    }

    static class AutoCloseableResource implements AutoCloseable {
        @Override
        public void close() throws Exception {
            throw new Exception(
                "Secondary exception from implicit finally close()"
            );
        }
    }
}
